}
function profile_wa(?array $item=null): string {
  $message=$item?implode("\n",['Halo Ruethies Patisserie! Saya ingin memesan '.$item['id']['n'].'.','Produk: '.CATALOG_ORIGIN.catalog_path($item),'Mohon konfirmasi ketersediaan dan harga.']):'Halo Ruethies Patisserie! Saya ingin bertanya tentang menu dan pemesanan.';
  return 'https://wa.me/6285139281257?text='.rawurlencode($message);
}
function profile_link(string $url,string $id,string $en,string $class='rp-link',bool $external=false): string {
  return '<a class="'.$class.'" href="'.catalog_escape($url).'"'.($external?' target="_blank" rel="noopener"':'').($url===profile_wa()?' data-general-wa':'').'>'.profile_text($id,$en).'</a>';
}
function profile_public(array $items): array {return array_values(array_filter($items,fn($m)=>($m['available']??true)!==false));}
function profile_has_snack(array $items): bool {foreach($items as $m)if(($m['slug']??'')==='snackbox'&&($m['available']??true)!==false)return true;return false;}
function profile_picture(array $item,bool $eager=false,bool $full=false): string {
