  $body.='</nav><form class="rp-search" method="get" action="/menu/"><input type="hidden" name="kategori" value="'.catalog_escape($cat).'"><label for="rp-search">'.profile_text('Cari sajian','Search treats').'</label><input id="rp-search" name="q" type="search" maxlength="100" value="'.catalog_escape($q).'" placeholder="Brownies, pastel, snackbox…"><button class="rp-button" type="submit">'.profile_text('Cari','Search').'</button></form><div class="rp-grid rp-catalog-grid" id="rp-catalog">'.implode('',array_map('profile_card',$visible)).'</div>';
