}
function profile_information(string $template,string $path,array $faq,array $gallery=[],array $items=[]): string {
  [$title,$english]=PROFILE_PAGES[$path];$body='<main id="home" class="container rp-page">'.profile_breadcrumb($title,$english).'<header class="rp-page-title"><p class="rp-kicker">RUETHIES PATISSERIE</p><h1>'.profile_text($title,$english).'</h1></header>';
  $image='images/menu/snackbox.jpg';$schemas=[seo_business($template)];$snapshot=['hasSnackBox'=>profile_has_snack($items)];
  if($path==='/tentang-kami/'){
    $body.='<section class="rp-story rp-about-story"><div class="rp-story-photo">'.profile_picture(['img'=>$image,'id'=>['n'=>'Snackbox Ruethies'],'en'=>['n'=>'Ruethies snack boxes']],true).'</div><div><p class="rp-kicker">#MadeWithDelicacy</p><h2>'.profile_text('Sajian untuk momen bersama','Treats for shared moments').'</h2>'.profile_text('Ruethies Patisserie berada di Lippo Cikarang. Katalog kami mencakup kue klasik, camilan gurih, snack box, dan platter.','Ruethies Patisserie is based in Lippo Cikarang. Our catalogue includes classic cakes, savoury bites, snack boxes and platters.','p').profile_text('Kenali pilihan sajian melalui foto produk kami, lalu bicarakan jumlah dan tanggal kebutuhan bersama tim Ruethies melalui WhatsApp.','Explore our treats through product photos, then discuss quantities and dates with the Ruethies team on WhatsApp.','p').profile_link('/menu/','Jelajahi menu →','Explore the menu →','rp-button').'</div></section><section class="rp-section" id="galeri"><h2>'.profile_text('Galeri Ruethies','Ruethies Gallery').'</h2><div class="rp-gallery">';
    foreach($gallery as$i=>$a)$body.='<figure><a class="rp-gallery-photo" href="/'.catalog_escape($a['imgFull']??$a['img']).'" data-gallery-index="'.$i.'" aria-haspopup="dialog"><img src="/'.catalog_escape($a['img']).'" width="640" height="480" loading="lazy" decoding="async" alt="'.catalog_escape($a['id']['cap']).'"></a><figcaption>'.profile_text($a['id']['cap'],$a['en']['cap']??$a['id']['cap']).'</figcaption></figure>';
    $body.='</div></section><dialog id="rp-gallery-dialog" class="rp-gallery-dialog" aria-label="Galeri Ruethies"><button type="button" id="rp-gallery-close" aria-label="Tutup foto">×</button><img id="rp-gallery-image" width="1200" height="900" alt=""><p id="rp-gallery-caption"></p><div class="rp-gallery-controls"><button type="button" data-gallery-prev aria-label="Foto sebelumnya">‹</button><span id="rp-gallery-count"></span><button type="button" data-gallery-next aria-label="Foto berikutnya">›</button></div></dialog>';$snapshot['gallery']=$gallery;
  }elseif($path==='/hubungi-kami/'){
    $directions='https://www.google.com/maps/dir/?api=1&destination=-6.3443722,107.1490519';
    $body.='<section class="rp-contact-layout"><div><h2>Ruethies Patisserie</h2><address>Ruko The Neo Patio East No. 51<br>Lippo Cikarang, Cikarang Selatan<br>Kabupaten Bekasi, Jawa Barat 17530</address>'.profile_text('Setiap hari · 09.00–21.00 WIB','Daily · 9 AM–9 PM WIB','p').'<p>WhatsApp: <a href="https://wa.me/6285139281257" target="_blank" rel="noopener">0851-3928-1257</a><br>Email: <a href="mailto:info@ruethiespatisserie.com">info@ruethiespatisserie.com</a></p><div class="rp-actions">'.profile_link($directions,'Dapatkan rute →','Get directions →','rp-button rp-button-outline',true).profile_link(profile_wa(),'WhatsApp Ruethies','WhatsApp Ruethies','rp-button',true).'</div></div><div class="rp-map"><div id="rp-map-placeholder"><p class="rp-kicker">LIPPO CIKARANG · NO. 51</p><h2>'.profile_text('Sampai bertemu di Ruethies','See you at Ruethies').'</h2>'.profile_link($directions,'Buka petunjuk arah →','Open directions →','rp-link',true).'<button id="rp-map-load" class="rp-button rp-button-outline" type="button" hidden>'.profile_text('Tampilkan peta interaktif','Show interactive map').'</button></div><iframe id="rp-map-frame" width="600" height="400" loading="lazy" referrerpolicy="no-referrer-when-downgrade" title="Lokasi Ruethies Patisserie" hidden></iframe></div></section><section class="rp-section rp-narrow"><h2>'.profile_text('Sebelum berkunjung','Before your visit').'</h2>'.profile_text('Untuk pengambilan pesanan, konfirmasikan tanggal dan waktu bersama tim Ruethies melalui WhatsApp sebelum datang.','For order pickup, confirm the date and time with our team on WhatsApp before visiting.','p').profile_link('/menu/','Lihat menu sebelum datang →','Explore the menu before visiting →').'</section>';
  }else{
    $body.='<section class="rp-section rp-first-section">'.profile_steps().'</section><section class="rp-section" id="ketentuan"><div class="rp-section-heading"><h2>'.profile_text('Sebelum mengonfirmasi pesanan','Before confirming your order').'</h2></div><div class="rp-order-info"><div><h3>'.profile_text('Pilihan & waktu kebutuhan','Selections & timing').'</h3>'.profile_text('Tanyakan ketersediaan, harga, minimum jumlah, serta waktu persiapan untuk produk yang Anda pilih.','Ask about availability, prices, minimum quantities and preparation time for your selected products.','p').'</div><div><h3>'.profile_text('Pengambilan & pengantaran','Pickup & delivery').'</h3>'.profile_text('Konfirmasikan cara menerima pesanan. Untuk pengantaran, tanyakan area layanan, biaya, dan ketentuannya melalui WhatsApp.','Confirm how you will receive the order. For delivery, ask about service areas, fees and terms on WhatsApp.','p').'</div><div><h3>'.profile_text('Perubahan & pesanan custom','Changes & custom orders').'</h3>'.profile_text('Sampaikan kebutuhan khusus sebelum konfirmasi. Tanyakan ketentuan perubahan dan pembatalan langsung kepada tim Ruethies.','Share special requests before confirming. Ask our team about changes and cancellation terms.','p').'</div></div></section><section class="rp-section"><h2>'.profile_text('Yang perlu Anda ketahui','Your questions, answered').'</h2>'.profile_faq($faq).'</section>'; $schemas[]=seo_faq_schema($faq);$snapshot['faq']=$faq;
  }
  $body.='<section class="rp-bottom-cta"><h2>'.profile_text('Temukan sajian untuk momen Anda','Find treats for your occasion').'</h2>'.profile_link('/menu/','Lihat menu & pesan →','Explore menu & order →','rp-button').'</section></main>';
  $schemas[]=['@context'=>'https://schema.org','@type'=>$path==='/tentang-kami/'?'AboutPage':($path==='/hubungi-kami/'?'ContactPage':'WebPage'),'url'=>CATALOG_ORIGIN.$path,'name'=>$title,'inLanguage'=>'id'];
  $schemas[]=['@context'=>'https://schema.org','@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Beranda','item'=>CATALOG_ORIGIN.'/'],['@type'=>'ListItem','position'=>2,'name'=>$title,'item'=>CATALOG_ORIGIN.$path]]];
  $descriptions=[
    '/tentang-kami/'=>'Kenali Ruethies Patisserie di Lippo Cikarang. Jelajahi kue klasik, camilan gurih, snack box dan galeri produk kami.',
    '/hubungi-kami/'=>'Alamat, jam buka, WhatsApp dan email Ruethies Patisserie di Lippo Cikarang. Dapatkan rute ke Ruko The Neo Patio East No. 51.',
    '/cara-pesan/'=>'Panduan memesan kue dan snack box Ruethies melalui WhatsApp. Sampaikan pilihan, jumlah serta tanggal dan konfirmasikan kebutuhan bersama tim kami.',
  ];
  return profile_shell($template,$body,$path,$title.' | Ruethies Patisserie',$descriptions[$path],$image,$schemas,$snapshot);
}
function profile_gallery_read(string $path): array {
  $items=catalog_read_json($path);
  foreach($items as $a){
    if(!is_array($a))throw new RuntimeException('Galeri tidak valid.');
    foreach(['img','imgFull']as$key)if(isset($a[$key])&&(!is_string($a[$key])||!preg_match('~\Aimages/[a-zA-Z0-9/_-]+\.(?:jpg|jpeg|png|webp)\z~D',$a[$key])))throw new RuntimeException('Foto galeri tidak valid.');
    if(!isset($a['img'])||!is_string($a['id']['cap']??null)||isset($a['en']['cap'])&&!is_string($a['en']['cap']))throw new RuntimeException('Caption galeri tidak valid.');
  }return $items;
}
